import { useState } from 'react'
import React, {useEffect, useRef} from 'react'
import QRCode from 'easyqrcodejs';
import {useSelector} from "react-redux";
import AppId from "../../../configs/appId";
import { Input } from 'reactstrap'
import {FormattedMessage} from "react-intl";
import {Clipboard, Download} from "react-feather";
import {toastSuccess} from "../../../utility";
import { USER_ROLE } from '../../../configs/app-configs'

export const ShareWithFriends = () => {
  const { user } = useSelector((state) =>
    state.customizer.appId === AppId.ELITE_APP ? state.auth.guest : state.auth
  )
  const [qrCodeInstance, setQRCodeInstance] = useState(null)
  const qrCode = useRef()
  // const shareUrl = `${document.location.origin}/home?refId=${user.username}`;
  const shareUrl = `${document.location.origin}/home?refId=${user.refId}`
  useEffect(() => {
    const options = {
      text: shareUrl,
      colorDark: '#106D5A',
      correctLevel: QRCode.CorrectLevel.H,
      logo: 'data:image/svg+xml;base64,',
      dotScale: 0.5,
    }
    setQRCodeInstance(new QRCode(qrCode.current, options))
  }, [])
  const onClickCopy = async () => {
    await navigator.clipboard.writeText(shareUrl)
    toastSuccess(<FormattedMessage id='setting.copySuccess' />)
  }
  const onClickDownloadQRCode = () => {
    const canvas = document.querySelector('#qrcode canvas')
    const pngUrl = canvas.toDataURL('image/png').replace('image/png', 'image/octet-stream')
    let downloadLink = document.createElement('a')
    downloadLink.href = pngUrl
    downloadLink.download = 'inon-qrcode.png'
    document.body.appendChild(downloadLink)
    downloadLink.click()
    document.body.removeChild(downloadLink)
  }
  const onChangeQRCode = (e) => {
    qrCodeInstance.makeCode(e.target.value)
  }
  return (
    <React.Fragment>
      <div className='text-center my-4'>
        <div id='qrcode' ref={qrCode} />
        <div>
          <span className='text-primary cursor-pointer' onClick={onClickDownloadQRCode}>
            <Download size={24} />
          </span>
        </div>
        <div className='d-flex align-items-center justify-content-center mt-3'>
          <Input
            defaultValue={shareUrl}
            onChange={onChangeQRCode}
            disabled={user.groupId !== USER_ROLE.ADMIN}
          />
          <span className='cursor-pointer ml-2 text-primary' onClick={onClickCopy}>
            <Clipboard />
          </span>
        </div>
      </div>
    </React.Fragment>
  )
}
